INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Arbeitszeitgesetz für alle Arbeitnehmer in Deutschland?', 2, '[{"text": "Nein", "correct": true, "because": "Ausnahmen z.B. Führungskräfte"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Arbeitszeitgesetz?', 3, '[{"text": "Schutz der Gesundheit", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Produktivitätssteigerung", "correct": false, "because": "Indirekt"}, {"text": "Kostenreduktion", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelungen enthält das Arbeitszeitgesetz?', 5, '[{"text": "Maximale Arbeitszeit", "correct": true, "because": "8 Stunden pro Tag"}, {"text": "Ruhepausen", "correct": true, "because": "Mindestpausen vorgeschrieben"}, {"text": "Urlaubsanspruch", "correct": false, "because": "Bundesurlaubsgesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Arbeitszeitgesetz schreibt Ruhezeiten vor. b) Es gilt nicht für Teilzeitkräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt auch für Teilzeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Arbeitszeitgesetz?', 4, '[{"text": "Arbeitszeitbegrenzung", "correct": false, "because": "Kernregelung"}, {"text": "Pausenregelung", "correct": false, "because": "Pflichtvorgabe"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Gesetzesfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Arbeitszeitgesetz Nachtarbeit regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Spezielle Vorschriften"}, {"text": "Nein", "correct": false, "because": "Teil des Gesetzes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitszeit ist im Arbeitszeitgesetz maximal erlaubt?', 3, '[{"text": "8 Stunden", "correct": true, "because": "Standardgrenze"}, {"text": "10 Stunden", "correct": false, "because": "Mit Ausnahmen"}, {"text": "12 Stunden", "correct": false, "because": "Nur in Sonderfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Einhaltung des Arbeitszeitgesetzes?', 5, '[{"text": "Arbeitszeitdokumentation", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Ruhezeiten", "correct": true, "because": "11 Stunden zwischen Schichten"}, {"text": "Urlaubsplanung", "correct": false, "because": "Anderes Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Arbeitszeitgesetz schützt vor Überarbeitung. b) Es gilt nicht für Selbstständige. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Selbstständige ausgenommen"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Arbeitszeitgesetz unwichtig?', 4, '[{"text": "Pausenregelung", "correct": false, "because": "Schlüsselaspekt"}, {"text": "Maximale Arbeitszeit", "correct": false, "because": "Kernvorgabe"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Gesetzesfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Regelt das Arbeitszeitgesetz Sonntagsarbeit?', 2, '[{"text": "Ja", "correct": true, "because": "Ruhetag vorgeschrieben"}, {"text": "Nein", "correct": false, "because": "Teil des Gesetzes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt das Arbeitszeitgesetz?', 4, '[{"text": "Gesundheitsschutz", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Work-Life-Balance", "correct": true, "because": "Sichert Freizeit"}, {"text": "Höhere Gewinne", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Arbeitszeitgesetz flexible Arbeitszeiten verbietet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel innerhalb Grenzen"}, {"text": "Ja", "correct": false, "because": "Flexibilität erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Arbeitszeitgesetz?', 3, '[{"text": "Ruhezeiten", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Produktivität", "correct": false, "because": "Sekundär"}, {"text": "Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Arbeitszeitgesetz limitiert Arbeitsstunden. b) Es gilt nicht für Schichtarbeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt auch für Schichten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Verstoß gegen das Arbeitszeitgesetz?', 5, '[{"text": "Gesundheitsrisiken", "correct": true, "because": "Überlastung möglich"}, {"text": "Bußgelder", "correct": true, "because": "Rechtliche Konsequenz"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Arbeitszeitgesetz unwichtig?', 3, '[{"text": "Arbeitszeitbegrenzung", "correct": false, "because": "Kernvorgabe"}, {"text": "Ruhepausen", "correct": false, "because": "Schutzmaßnahme"}, {"text": "Mitarbeiterschulung", "correct": true, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erlaubt das Arbeitszeitgesetz Überstunden?', 3, '[{"text": "Ja", "correct": true, "because": "Bis 10 Stunden möglich"}, {"text": "Nein", "correct": false, "because": "Regelung vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Arbeitszeitgesetz Pausen vorschreibt?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzlich geregelt"}, {"text": "Nein", "correct": false, "because": "Teil des Gesetzes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regel wähle ich für Nachtarbeit im Arbeitszeitgesetz?', 4, '[{"text": "Besondere Pausen", "correct": true, "because": "Schutz bei Nacht"}, {"text": "Maximale Arbeitszeit", "correct": false, "because": "Allgemeine Regel"}, {"text": "Urlaubsanspruch", "correct": false, "because": "Anderes Gesetz"}]');
